class Solution:
    def tallestAhead(self, heights: List[int]) -> List[int]:
        n = len(heights)
        out = []
        for i in range(n):
            best = -1
            for j in range(i + 1, n):
                best = max(best, heights[j])
            out.append(best)
        return out

