class Solution {
    public int[] tallestAhead(int[] heights) {
        int n = heights.length;
        int[] out = new int[n];
        for (int i = 0; i < n; i++) {
            int best = -1;
            for (int j = i + 1; j < n; j++) best = Math.max(best, heights[j]);
            out[i] = best;
        }
        return out;
    }
}

