int* tallestAhead(int* heights, int heightsSize, int* returnSize) {
    int n = heightsSize;
    int* out = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        int best = -1;
        for (int j = i + 1; j < n; j++) if (heights[j] > best) best = heights[j];
        out[i] = best;
    }
    *returnSize = n;
    return out;
}

