class Solution {
    public int[] tallestAhead(int[] heights) {
        int[] out = new int[heights.length];
        int best = -1;
        for (int i = heights.length - 1; i >= 0; i--) {
            out[i] = best;
            best = Math.max(best, heights[i]);
        }
        return out;
    }
}

